mapper.sql:
from edu_enrollment e join edu_course_schedule s on s.schedule_id=e.schedule_id
left join edu_student_lesson_account a on a.account_id=e.lesson_account_id and a.parent_id=e.parent_id
left join edu_student st on st.student_id=coalesce(e.student_id,a.student_id)
where e.del_flag='0' and coalesce(e.bill_type,'') != 'CART_ORDER'
  and coalesce(e.enrollment_status,'') not in ('2','3','已取消','已拒绝','老师已拒绝')
and s.course_year=#{year}
and s.term_name=#{term}
and trim(s.grade_name) in ('一年级','二年级','三年级','四年级','五年级','六年级','小学一年级','小学二年级','小学三年级','小学四年级','小学五年级','小学六年级','小一','小二','小三','小四','小五','小六','1年级','2年级','3年级','4年级','5年级','6年级')
and trim(s.grade_name) in ('初一','初二','初三','初中一年级','初中二年级','初中三年级','七年级','八年级','九年级','7年级','8年级','9年级')
and trim(s.grade_name) in ('高一','高二','高三','高中一年级','高中二年级','高中三年级')
and s.grade_name=#{grade}
and s.subject_name=#{subject}
and s.teacher_id=#{teacherId}
